        <section class="hero <?php echo e($viewMode === 'category' ? 'category-hero' : ''); ?>" <?php if($viewMode === 'category' && filled($activeCategory?->banner_image_url)): ?> style="background:linear-gradient(90deg,rgba(15,23,42,.74),rgba(15,23,42,.34)),url('<?php echo e($activeCategory->banner_image_url); ?>') center/cover" <?php endif; ?>><div class="wrap"><h1><?php echo e($title); ?></h1><p><?php echo e($description); ?></p></div></section>
        <section class="catalog"><div class="wrap catalog-layout">
            <aside class="filter-card"><div class="filter-title">Categories</div><a class="cat-link <?php echo e(!$activeCategory ? 'active' : ''); ?>" href="<?php echo e($shopUrl); ?>"><span>All products</span></a><?php $__currentLoopData = $categories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $category): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><a class="cat-link <?php echo e($activeCategory?->id === $category->id ? 'active' : ''); ?>" href="<?php echo e($categoryUrl($category)); ?>"><span><?php echo e($category->name); ?></span><span><?php echo e($category->products_count); ?></span></a><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></aside>
            <div>
                <form class="toolbar" method="get"><div class="search"><input class="input" type="search" name="q" value="<?php echo e(request('q')); ?>" placeholder="Search products"><button class="btn" type="submit">Search</button></div><div style="display:flex;gap:8px;flex-wrap:wrap"><select class="select" name="stock" onchange="this.form.submit()"><option value="">All availability</option><option value="in" <?php if(request('stock')==='in'): echo 'selected'; endif; ?>>In stock</option></select><select class="select" name="sort" onchange="this.form.submit()"><option value="featured" <?php if(request('sort','featured')==='featured'): echo 'selected'; endif; ?>>Featured</option><option value="newest" <?php if(request('sort')==='newest'): echo 'selected'; endif; ?>>Newest</option><option value="price_asc" <?php if(request('sort')==='price_asc'): echo 'selected'; endif; ?>>Price: low to high</option><option value="price_desc" <?php if(request('sort')==='price_desc'): echo 'selected'; endif; ?>>Price: high to low</option><option value="title_asc" <?php if(request('sort')==='title_asc'): echo 'selected'; endif; ?>>Name: A–Z</option></select></div></form>
                <?php if($products->count()): ?><div class="grid"><?php $__currentLoopData = $products; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php ($range=$priceRange($item)); ?><a class="product-card" href="<?php echo e($productUrl($item)); ?>"><?php if($item->isOnSale()): ?><span class="badge sale">Sale</span><?php elseif($item->is_featured): ?><span class="badge">Featured</span><?php endif; ?><div class="card-media"><?php if($item->featured_image_url): ?><img src="<?php echo e($item->featured_image_url); ?>" alt="<?php echo e($item->featured_image_alt ?: $item->title); ?>" loading="lazy"><?php else: ?><div class="placeholder"><?php echo e($item->title); ?></div><?php endif; ?></div><div class="card-body"><h3 class="card-title"><?php echo e($item->title); ?></h3><div class="price"><?php if($range['min'] !== null && $range['max'] !== null && $range['min'] !== $range['max']): ?><span><?php echo e($money($range['min'])); ?> – <?php echo e($money($range['max'])); ?></span><?php else: ?><span><?php echo e($money($range['min'])); ?></span><?php endif; ?> <?php if(!$item->isVariable() && $item->isOnSale()): ?><span class="old"><?php echo e($money($item->regular_price_minor)); ?></span><?php endif; ?></div></div></a><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php if($products->lastPage()>1): ?><div class="pagination"><?php for($p=1;$p<=$products->lastPage();$p++): ?><?php if($p===$products->currentPage()): ?><span class="current"><?php echo e($p); ?></span><?php else: ?><a href="<?php echo e($products->url($p)); ?>"><?php echo e($p); ?></a><?php endif; ?> <?php endfor; ?></div><?php endif; ?> <?php else: ?><div class="empty"><strong>No products found</strong><div>Try a different search, category, or availability filter.</div></div><?php endif; ?>
            </div>
        </div></section>
